for A in range(256):
    ip = ip_address(f'201.154.34.{A}')
    net = ip_network(f'{ip}/{mask}', False)
    if ip in net.hosts():
        if all(
            f'{int(ip):032b}'[16:24].count('0') >
            f'{int(ip):032b}'[24:32].count('0')
            for ip in net.hosts()
        ):
